package com.lianxibu.site.controller.learning;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.learning.OwnerPackageReadService;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class OwnerPackageControllerTest {
 IdentityService auth;OwnerPackageReadService service;ObjectProvider<OwnerPackageReadService> provider;MockMvc mvc;final IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");
 @BeforeEach @SuppressWarnings("unchecked") void setup(){auth=mock(IdentityService.class);service=mock(OwnerPackageReadService.class);var identity=(ObjectProvider<IdentityService>)mock(ObjectProvider.class);provider=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);when(provider.getIfAvailable()).thenReturn(service);when(auth.authenticate("fictional-session")).thenReturn(owner);mvc=MockMvcBuilders.standaloneSetup(new OwnerPackageController(identity,provider)).build();}
 static String path(){return "/admin/learning/packages/fictional-package";}
 static jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
 @Test void unauthorizedAndNonOwnerNeverReachStorage()throws Exception{mvc.perform(get(path()).param("unknown","fictional")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));when(auth.authenticate("fictional-session")).thenReturn(new IdentityService.Actor("fictional-user","user"));mvc.perform(get(path()).cookie(cookie()).param("unknown","fictional")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void anyQueryIsClosedAndMissingProviderOrTypedFailuresRecover()throws Exception{mvc.perform(get(path()).cookie(cookie()).param("page","1","2")).andExpect(status().isBadRequest());verifyNoInteractions(service);when(provider.getIfAvailable()).thenReturn(null);mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1"));when(provider.getIfAvailable()).thenReturn(service);for(RuntimeException e:List.of(new OwnerPackageReadService.Missing(),new OwnerPackageReadService.Denied(),new IllegalArgumentException("Fictional internal detail"),new IllegalStateException("Fictional internal detail"))){doThrow(e).when(service).read(owner,"fictional-package");var r=mvc.perform(get(path()).cookie(cookie())).andExpect(status().is(e instanceof OwnerPackageReadService.Missing?404:e instanceof OwnerPackageReadService.Denied?403:e instanceof IllegalArgumentException?422:503)).andReturn();assertFalse(r.getResponse().getContentAsString().contains("internal detail"));}}
 @Test void actualCurrentDraftZeroEmptyAndUnknownMetadataRemainWhole()throws Exception{when(provider.getIfAvailable()).thenReturn(new OwnerPackageReadService(id->new OwnerPackageReadService.Snapshot(id,"Fictional draft","",0L,"draft")));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(jsonPath("$.data.revision").value(0)).andExpect(jsonPath("$.data.description").value("")).andExpect(jsonPath("$.data.state").value("draft")).andExpect(jsonPath("$.data.answers").doesNotExist()).andExpect(header().string("Cache-Control","no-store"));when(provider.getIfAvailable()).thenReturn(new OwnerPackageReadService(id->new OwnerPackageReadService.Snapshot(id,null,null,null,null)));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(jsonPath("$.data.revision").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.description").value(org.hamcrest.Matchers.nullValue()));}
 @Test void maximalUnicodeSurvivesEnvelopeAndUnprovenProjectionCannotLeak()throws Exception{when(provider.getIfAvailable()).thenReturn(new OwnerPackageReadService(id->new OwnerPackageReadService.Snapshot(id,"🙂".repeat(200),"🙂".repeat(16384),1L,"draft")));var r=mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andReturn().getResponse();assertTrue(r.getContentAsByteArray().length<1024*1024);var x=tools.jackson.databind.json.JsonMapper.shared().readTree(r.getContentAsByteArray());assertEquals(16384,x.get("data").get("description").textValue().codePointCount(0,32768));when(provider.getIfAvailable()).thenReturn(service);when(service.read(owner,"fictional-package")).thenReturn(Map.of("id","fictional-other","raw_json","Fictional must not leak"));var bad=mvc.perform(get(path()).cookie(cookie())).andExpect(status().isServiceUnavailable()).andReturn();assertFalse(bad.getResponse().getContentAsString().contains("must not leak"));}
}
